query HomeQuery {
  ...LayoutFragment
  homePages: placedPages(where: {home: true}, first: 4) {
    nodes {
      id
      title
      slug
      excerpt
      accent
    }
  }
  latestNews: pageItemsOfPage(where: {page: "news"}, first: 1) {
    nodes {
      id
      title
      slug
      excerpt
      status
      publishedAt
    }
  }
  pageBySlug(slug: "home") {
    id
    title
    slug
    content
    excerpt
    status
    publishedAt
    createdAt
    updatedAt
  }
}

fragment LayoutFragment on RootQuery {
  viewer {
    id
    displayName
    role
  }
  navigationPages: placedPages(where: {home: false}, first: 100) {
    nodes {
      id
      title
      slug
      accent
    }
  }
}

query PageQuery(
  $slug: String!
  $after: String
) {
  ...LayoutFragment
  pageBySlug(slug: $slug) {
    id
    title
    slug
    content
    excerpt
    status
    publishedAt
    createdAt
    updatedAt
    defaultItemKind
  }
  pageItemsOfPage(where: {page: $slug}, first: 20, after: $after) {
    nodes {
      id
      title
      slug
      excerpt
      content
      status
      publishedAt
      author {
        displayName
      }
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

fragment LayoutFragment on RootQuery {
  viewer {
    id
    displayName
    role
  }
  navigationPages: placedPages(where: {home: false}, first: 100) {
    nodes {
