}

query PageItemQuery(
  $page: String!
  $slug: String!
) {
  ...LayoutFragment
  pageBySlug(slug: $page) {
    id
    title
    slug
  }
  pageItemBySlug(slug: $slug) {
    id
    title
    slug
    content
    excerpt
    status
    publishedAt
    createdAt
    updatedAt
    kind
    enquiryUrl
    author {
      displayName
    }
    page {
      id
    }
  }
  pageOrder: pageItemsOfPage(where: {page: $page}, first: 100) {
    nodes {
      slug
      title
      status
      id
    }
  }
}

