query AdminQuery {
  ...AdminLayoutFragment
  viewer {
    id
  }
  pages: recentPages(first: 5) {
    totalCount
    nodes {
      id
      title
      status
      updatedAt
    }
  }
  publishedPages: recentPages(where: {status: PUBLISHED}, first: 0) {
    totalCount
  }
  items: recentPageItems(first: 5) {
    totalCount
    nodes {
      id
      title
      status
      updatedAt
      kind
      page {
        slug
        id
      }
    }
  }
  itemPages: pages(first: 100) {
    nodes {
      id
      title
      slug
      defaultItemKind
      itemCount
      publishedItemCount
    }
  }
}

fragment AdminLayoutFragment on RootQuery {
  viewer {
